describe("replaceAdrStatus", () => {
  it("aligns plain and bold ADR status metadata without changing other text", () => {
    expect(replaceAdrStatus("# Decision\n- Status: Proposed\n\nBody\n", "accepted")).toBe(
      "# Decision\n- Status: Accepted\n\nBody\n"
    );
    expect(replaceAdrStatus("# Decision\n- **Status:** Proposed\n", "rejected")).toBe(
      "# Decision\n- **Status:** Rejected\n"
    );
    expect(replaceAdrStatus("# No status\n", "accepted")).toBeNull();
  });
});

describe("parseAdrMetadata", () => {
  it("parses plain and bold status metadata and normalizes paths", () => {
    expect(
      parseAdrMetadata(
        "docs\\adr\\0026-constitution.md",
        "# Constitution\n\n- **Status:** Proposed\n",
        "workspace-sensor"
      )
    ).toEqual({
      adr_path: "docs/adr/0026-constitution.md",
      title: "Constitution",
      summary: "",
      status: "proposed",
      proposed_by: "workspace-sensor",
    });
    expect(parseAdrMetadata("docs/adr/0001.md", "# First\n- Status: Accepted\n")?.status).toBe(
      "accepted"
    );
  });

  it("rejects files without a structured title and supported status", () => {
    expect(parseAdrMetadata("docs/adr/no-title.md", "- Status: Proposed")).toBeNull();
    expect(parseAdrMetadata("docs/adr/no-status.md", "# No status")).toBeNull();
    expect(parseAdrMetadata("docs/adr/draft.md", "# Draft\n- Status: Draft")).toBeNull();
  });

  it("carries the ADR decision text so planning does not see only a title", () => {
    const parsed = parseAdrMetadata(
      "docs/adr/0099-example.md",
      "# ADR-0099\n\n- Status: Proposed\n\n## Context\n\nThe old way broke.\n\n## Decision\n\nDo the new thing.\n"
    );
    expect(parsed?.summary).toBe("Do the new thing.\n\nThe old way broke.");
  });

  /**
   * Bug: requiring an exact status match dropped every ADR whose status carried
   * a parenthetical note, e.g. `Accepted (implemented)`. ADR-0015 and ADR-0017
   * were therefore never registered in the design ledger at all, and the sync
   * still reported success, so the loss was invisible. A parenthetical is
   * commentary on a decision, not a different lifecycle state.
   */
  it("accepts a status carrying a parenthetical qualifier", () => {
    expect(
      parseAdrMetadata(
        "docs/adr/0017-working-memory.md",
        "# Working memory\n- Status: Accepted (implemented)\n"
      )?.status
    ).toBe("accepted");
    expect(
      parseAdrMetadata(
        "docs/adr/0015-advisory-symbol-leases.md",
        "# Advisory symbol leases\n- Status: Accepted (no symbol-lease primitive)\n"
      )?.status
    ).toBe("accepted");
  });

  /**
   * This assertion used to require `null` for a superseded ADR, which is why
   * ADR-0018 and ADR-0032 were absent from the board. ADR-0050 says superseding
   * keeps the row accepted and adds a successor link, so `accepted` is what a
   * superseded design's status *is* — and registering it is the precondition
   * for ever recording the supersession, which is guarded on an accepted row.
   *
   * A status naming a state the ledger genuinely has no room for is still
   * refused, and still reported by the caller rather than dropped in silence.
   */
  it("registers a superseded ADR as accepted, and still refuses an unknown state", () => {
    expect(
      parseAdrMetadata(
        "docs/adr/0032-single-checkout.md",
        "# Single checkout\n- Status: Superseded by\n   [ADR-0038](0038-x.md)\n"
      )?.status
    ).toBe("accepted");
    expect(
      parseAdrMetadata("docs/adr/0099-draft.md", "# Draft\n- Status: Deprecated\n")
    ).toBeNull();
  });
});

describe("rawAdrStatus / normalizeAdrStatus", () => {
  it("reports the declared status so a skipped ADR can say why it was skipped", () => {
    expect(rawAdrStatus("# T\n- **Status:** Superseded by [ADR-0038](x.md)\n")).toBe(
      "superseded by [adr-0038](x.md)"
    );
    expect(rawAdrStatus("# T\nno status line")).toBeUndefined();
  });

  // ADR-0032 wraps its successor onto the following line. A pattern that
  // stopped at the newline read a bare "Superseded by" and lost the reference
  // that was one line further down — the same bug scripts/adr-files.mjs already
  // documents and handles.
  it("reads a Status value that wraps onto a continuation line", () => {
    expect(
      rawAdrStatus("# T\n- Status: Superseded by\n   [ADR-0038](0038-x.md)\n- Date: 2026\n")
    ).toBe("superseded by [adr-0038](0038-x.md)");
  });

  it("stops at the next bullet rather than swallowing it", () => {
    expect(rawAdrStatus("# T\n- Status: Accepted\n- Date: 2026-07-30\n")).toBe("accepted");
  });

  /**
   * ADR-0050: superseding keeps the row **accepted** and adds a link to the
   * successor, so a live design is one with no `superseded_by`. The status of a
   * superseded design is therefore `accepted`, and refusing to map it dropped
   * ADR-0018 and ADR-0032 off the board entirely.
   *
   * The successor link is deliberately not derived here. Supersession is an
   * attributed human act guarded on an accepted row with a recorded decider and
   * a registered replacement; a scan that asserted it would repeat the mistake
   * ADR-0042 refuses when it declines to auto-retire on a missing file.
   */
  it("maps a qualified status to its lifecycle state and refuses an unknown one", () => {
    expect(normalizeAdrStatus("accepted (implemented)")).toBe("accepted");
    expect(normalizeAdrStatus("proposed")).toBe("proposed");
    expect(normalizeAdrStatus("superseded by [adr-0038](x.md)")).toBe("accepted");
    expect(normalizeAdrStatus("superseded")).toBe("accepted");
    expect(normalizeAdrStatus("draft")).toBeUndefined();
    expect(normalizeAdrStatus(undefined)).toBeUndefined();
  });
});

describe("isAdrFile", () => {
  // docs/adr/README.md is generated by scripts/adr-index.mjs. Scanning it
  // produced a "no readable title or Status line" skip on every load, which
  // inflated the count and made a working warning read like a defect.
  it("accepts a numbered ADR and refuses the generated index", () => {
    expect(isAdrFile("docs/adr/0074-coverage-is-a-prediction.md")).toBe(true);
    expect(isAdrFile("docs/adr/README.md")).toBe(false);
    expect(isAdrFile("docs/adr/notes.md")).toBe(false);
  });

  it("is indifferent to path separators and directory depth", () => {
    expect(isAdrFile("docs\\adr\\0001-record-architecture-decisions.md")).toBe(true);
    expect(isAdrFile("0001-record-architecture-decisions.md")).toBe(true);
  });
});

/**
 * The property the Design Board actually needs: every ADR in this repository
 * can be read. Measured 2026-07-30, three of 74 matched files were dropped —
 * the generated index, and ADR-0018 and ADR-0032 for being superseded.
 *
 * `scripts/adr-files.mjs` already knew all of this, and says in its own header
 * that a second parser would drift from it. This test is what stops the two
 * drifting again: it reads the real corpus rather than a fixture, so a new ADR
 * written in a shape the extension cannot parse fails here.
 */
describe("every ADR in this repository is readable", () => {
  const adrDir = path.resolve(__dirname, "..", "..", "..", "docs", "adr");

  it("parses every numbered ADR file, skipping none", () => {
    const files = fs.readdirSync(adrDir).filter((name) => isAdrFile(name));
    expect(files.length).toBeGreaterThan(70);

    const unreadable = files.filter(
      (name) =>
        parseAdrMetadata(`docs/adr/${name}`, fs.readFileSync(path.join(adrDir, name), "utf8")) ===
        null
    );

    expect(unreadable).toEqual([]);
  });
});

describe("extractAdrSummary", () => {
  it("prefers the decision, then the context, and ignores other sections", () => {
    const adr = [
      "# ADR-0099: Example",
      "",
      "- Status: Proposed",
      "",
      "## Context",
      "",
      "The old way broke.",
      "",
      "## Decision",
      "",
      "Do the new thing.",
      "",
      "## Consequences",
      "",
      "Some cost.",
    ].join("\n");
    expect(extractAdrSummary(adr)).toBe("Do the new thing.\n\nThe old way broke.");
  });

  it("returns empty rather than inventing content when neither section exists", () => {
    expect(extractAdrSummary("# Title\n\n- Status: Accepted\n")).toBe("");
  });

  it("truncates a long decision at a line boundary", () => {
    const line = "x".repeat(120);
    const body = Array.from({ length: 40 }, () => line).join("\n");
    const summary = extractAdrSummary(`# T\n\n## Decision\n\n${body}\n`);
    expect(summary.length).toBeLessThanOrEqual(2000);
    expect(summary.split("\n").every((entry) => entry === line)).toBe(true);
  });
});

describe("designBoardRows", () => {
  it("orders actionable states before durable history", () => {
    const rows = designBoardRows([
      item({ id: "rejected", status: "rejected", created_at: 4 }),
      item({
        id: "materialized",
        status: "accepted",
        promotion_status: "materialized",
        created_at: 3,
      }),
      item({ id: "pending", status: "accepted", promotion_status: "pending", created_at: 2 }),
      item({ id: "proposed", created_at: 1 }),
      item({
        id: "historical",
        status: "accepted",
        promotion_status: "not_required",
        created_at: 5,
      }),
    ]);

    expect(rows.map((row) => row.contextValue)).toEqual([
      "proposed",
      "pending",
      "materialized",
      "historical",
      "rejected",
    ]);
  });

  it("shows materialized objective and task provenance", () => {
    const materialized = promotion();
    const rows = designBoardRows(
      [materialized.item],
      new Map([[materialized.item.id, materialized]])
    );

    expect(rows[0].description).toBe("materialized · 1 tasks · r1");
    expect(rows[0].tooltip).toContain("objective: Ship (goal:ship)");
    expect(rows[0].tooltip).toContain("tasks: 1; constraints: 1");
  });

  it("keeps historical accepted designs read-only while pending designs are actionable", () => {
    const rows = designBoardRows([
      item({ id: "historical", status: "accepted", promotion_status: "not_required" }),
      item({ id: "pending", status: "accepted", promotion_status: "pending" }),
    ]);

    expect(rows.find((row) => row.id === "pending")?.contextValue).toBe("pending");
    expect(rows.find((row) => row.id === "historical")?.contextValue).toBe("historical");
  });
});

describe("formatDesignPromotion", () => {
  it("renders objective, tasks, and constraints", () => {
    const markdown = formatDesignPromotion(promotion());
    expect(markdown).toContain("# Design materialization: Constitution");
    expect(markdown).toContain("**Objectives:** Ship (goal:ship)");
    expect(markdown).toContain("Implement — open (task:one)");
    expect(markdown).toContain("No shortcuts — constraint (goal:rule)");
  });

  it("renders no-work decisions and append-only repair history", () => {
    const current = promotion();
    current.mode = "no_work";
    current.revision = 2;
    current.goals = [];
    current.tasks = [];
    current.rationale = "Already implemented";
    const markdown = formatDesignPromotion(current, [
      {
        design_id: current.item.id,
        revision: 1,
        plan: { mode: "create" },
        actor: "reviewer",
        created_at: 10,
      },
      {
        design_id: current.item.id,
        revision: 2,
        plan: { mode: "no_work", rationale: "Already implemented" },
        actor: "second-reviewer",
        created_at: 11,
      },
    ]);
    expect(markdown).toContain("**Mode:** no_work");
    expect(markdown).toContain("**Objectives:** none");
    expect(markdown).toContain("r2 — no_work by second-reviewer: Already implemented");
  });
});

